package io.legado.app.help

import io.legado.app.data.entities.BookSource
import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.Test
import java.util.Base64

class LegacyCryptoCompatibilityTests {
    private val source = BookSource(bookSourceUrl = "https://legacy-crypto.example")
    private val text = "中文正文😀"
    private val aesKey = "0123456789abcdef"
    private val aesIv = "abcdef0123456789"
    private val aesTransformation = "AES/CBC/PKCS5Padding"

    // Independent OpenSSL vectors, not ciphertext generated by the bridge under test.
    private val aesHex = "b78d714b593cf89ed20b842d243e4c4e361a33fc6ad9260493291a663096fc3e"
    private val aesBase64 = "t41xS1k8+J7SC4QtJD5MTjYaM/xq2SYEkykaZjCW/D4="
    private val desHex = "7b5cb54b7f0349ce1098966c3bc56eb3ca1ba430d5acb0e7"
    private val desBase64 = "e1y1S38DSc4QmJZsO8Vus8obpDDVrLDn"
    private val tripleHex = "04bd72bf0f635f6d93b001b577d2b2095af54bf0e31fb362"
    private val tripleBase64 = "BL1yvw9jX22TsAG1d9KyCVr1S/DjH7Ni"

    private fun base64(value: String): String = Base64.getEncoder().encodeToString(value.toByteArray())
    private fun bytes(value: String): ByteArray = Base64.getDecoder().decode(value)

    @Test
    fun `all FU legacy AES decoders accept both hex and Base64 ciphertext`() {
        for (ciphertext in listOf(aesHex, aesBase64)) {
            assertArrayEquals(text.toByteArray(), source.aesDecodeToByteArray(ciphertext, aesKey, aesTransformation, aesIv))
            assertEquals(text, source.aesDecodeToString(ciphertext, aesKey, aesTransformation, aesIv))
            assertArrayEquals(text.toByteArray(), source.aesBase64DecodeToByteArray(ciphertext, aesKey, aesTransformation, aesIv))
            assertEquals(text, source.aesBase64DecodeToString(ciphertext, aesKey, aesTransformation, aesIv))
        }
        assertEquals(text, source.evalScript("java.aesBase64DecodeToString('$aesHex','$aesKey','$aesTransformation','$aesIv')"))
    }

    @Test
    fun `FU AES legacy encoders retain raw and Base64 byte representations`() {
        assertArrayEquals(bytes(aesBase64), source.aesEncodeToByteArray(text, aesKey, aesTransformation, aesIv))
        assertArrayEquals(aesBase64.toByteArray(), source.aesEncodeToBase64ByteArray(text, aesKey, aesTransformation, aesIv))
        assertEquals(aesBase64, source.aesEncodeToBase64String(text, aesKey, aesTransformation, aesIv))
    }

    @Test
    fun `FU aesEncodeToString keeps its historical decryption behavior despite its name`() {
        assertEquals(text, source.aesEncodeToString(aesHex, aesKey, aesTransformation, aesIv))
        assertEquals(text, source.evalScript("java.aesEncodeToString('$aesBase64','$aesKey','$aesTransformation','$aesIv')"))
    }

    @Test
    fun `FU AES ArgsBase64 decode decodes both key and IV and accepts hex ciphertext`() {
        for (ciphertext in listOf(aesHex, aesBase64)) {
            assertEquals(text, source.aesDecodeArgsBase64Str(ciphertext, base64(aesKey), "CBC", "PKCS5Padding", base64(aesIv)))
        }
    }

    @Test
    fun `FU AES ArgsBase64 encode uses original UTF8 key and IV despite its name`() {
        assertEquals(aesBase64, source.aesEncodeArgsBase64Str(text, aesKey, "CBC", "PKCS5Padding", aesIv))
        assertEquals(aesBase64, source.evalScript("java.aesEncodeArgsBase64Str('$text','$aesKey','CBC','PKCS5Padding','$aesIv')"))
        assertThrows(Exception::class.java) {
            source.aesEncodeArgsBase64Str(text, base64(aesKey), "CBC", "PKCS5Padding", base64(aesIv))
        }
    }

    @Test
    fun `FU legacy DES decoders accept hex and Base64 and encoders retain the wire bytes`() {
        for (ciphertext in listOf(desHex, desBase64)) {
            assertEquals(text, source.desDecodeToString(ciphertext, "12345678", "DES/CBC/PKCS5Padding", "abcdefgh"))
            assertEquals(text, source.desBase64DecodeToString(ciphertext, "12345678", "DES/CBC/PKCS5Padding", "abcdefgh"))
        }
        assertEquals(String(bytes(desBase64)), source.desEncodeToString(text, "12345678", "DES/CBC/PKCS5Padding", "abcdefgh"))
        assertEquals(desBase64, source.desEncodeToBase64String(text, "12345678", "DES/CBC/PKCS5Padding", "abcdefgh"))
    }

    @Test
    fun `FU 3DES uses a raw IV and only decodes the ArgsBase64 key`() {
        val key = "0123456789abcdefghijklmn"
        // Valid eight-byte IV whose Base64-decoded value is only six bytes.
        val iv = "YWJjZGVm"
        for (ciphertext in listOf(tripleHex, tripleBase64)) {
            assertEquals(text, source.tripleDESDecodeStr(ciphertext, key, "CBC", "PKCS5Padding", iv))
            assertEquals(text, source.tripleDESDecodeArgsBase64Str(ciphertext, base64(key), "CBC", "PKCS5Padding", iv))
        }
        assertEquals(tripleBase64, source.tripleDESEncodeBase64Str(text, key, "CBC", "PKCS5Padding", iv))
        assertEquals(tripleBase64, source.tripleDESEncodeArgsBase64Str(text, base64(key), "CBC", "PKCS5Padding", iv))
        assertEquals(text, source.evalScript("java.tripleDESDecodeArgsBase64Str('$tripleHex','${base64(key)}','CBC','PKCS5Padding','$iv')"))
    }

    @Test
    fun `FU legacy AES failures propagate so scripts can handle them`() {
        assertThrows(Exception::class.java) { source.aesDecodeToByteArray(aesBase64, "short", aesTransformation, aesIv) }
        assertThrows(Exception::class.java) { source.aesBase64DecodeToByteArray("00", aesKey, aesTransformation, aesIv) }
        assertThrows(Exception::class.java) { source.aesEncodeToByteArray(text, "short", aesTransformation, aesIv) }
        assertThrows(Exception::class.java) { source.aesEncodeToBase64ByteArray(text, "short", aesTransformation, aesIv) }
        assertEquals(true, source.evalScript("try { java.aesDecodeToString('$aesBase64','short','$aesTransformation','$aesIv'); false; } catch (error) { true; }"))
    }
}
